select jsonb_build_object('snapshot',s,'normalized',(select src.snapshot_doc-'relations'-'functions'||jsonb_build_object('relations',(select jsonb_agg(rel-'columns'-'constraints'-'indexes'||jsonb_build_object('columns',(select jsonb_agg(item order by pos) from jsonb_array_elements(rel->'columns') with ordinality e(item,pos) where not ((rel->>'relname',item->>'name') in (values ('campaigns','publish_key'),('campaigns','publish_error'),('campaigns','publish_started_at'),('campaigns','external_adset_id'),('campaigns','daily_budget_cents'),('creatives','external_image_hash'),('ad_accounts','min_daily_budget_cents'),('ad_accounts','min_budget_checked_at'),('businesses','geo_lat'),('businesses','geo_lng'),('businesses','cadastro_erro'),('businesses','whatsapp_do_anuncio'),('campaigns','ativando_em')))),'constraints',(select jsonb_agg(item order by item->>'name') from jsonb_array_elements(rel->'constraints') with ordinality e(item,pos) where not ((rel->>'relname',item->>'name') in (values ('campaigns','campaigns_publish_state_check'),('creatives','creatives_status_check'),('businesses','businesses_cadastro_estado_check'),('meta_connections','meta_connections_meta_user_id_nao_vazio'),('campaigns','campaigns_ativacao_carimbada_check'),('campaigns','campaigns_ativa_exige_carimbo_check'),('campaigns','campaigns_pausa_carimbada_check'),('campaigns','campaigns_pausada_exige_carimbo_check')))),'indexes',(select jsonb_agg(item order by item->>'name') from jsonb_array_elements(rel->'indexes') with ordinality e(item,pos) where not ((rel->>'relname',item->>'name') in (values ('campaigns','campaigns_publishing_idx'),('campaigns','campaigns_publish_key_idx'),('campaigns','campaigns_ativando_idx'),('campaigns','campaigns_esperando_ativacao_idx'),('businesses','businesses_cadastro_estado_idx'),('exclusoes_de_dados','exclusoes_de_dados_meta_user_id_idx'))))) order by rel->>'nspname',rel->>'relname') from jsonb_array_elements(src.snapshot_doc->'relations') rel where not (rel->>'nspname'='public' and rel->>'relname'='exclusoes_de_dados')),'functions',(select jsonb_agg(f order by f->>'schema',f->>'name',f->>'identity') from jsonb_array_elements(src.snapshot_doc->'functions') f where f->>'name' not in ('desautorizar_meta','apagar_dados_da_meta','status_da_exclusao'))) from(select s snapshot_doc) src),'delta',(select jsonb_build_object('columns',(select coalesce(jsonb_agg(jsonb_build_object('table',rel->>'relname','object',item) order by rel->>'relname',item->>'name'),'[]'::jsonb) from jsonb_array_elements(src.snapshot_doc->'relations') rel cross join lateral jsonb_array_elements(rel->'columns') item where (rel->>'relname',item->>'name') in (values ('campaigns','publish_key'),('campaigns','publish_error'),('campaigns','publish_started_at'),('campaigns','external_adset_id'),('campaigns','daily_budget_cents'),('creatives','external_image_hash'),('ad_accounts','min_daily_budget_cents'),('ad_accounts','min_budget_checked_at'),('businesses','geo_lat'),('businesses','geo_lng'),('businesses','cadastro_erro'),('businesses','whatsapp_do_anuncio'),('campaigns','ativando_em'))),'checks',(select coalesce(jsonb_agg(jsonb_build_object('table',rel->>'relname','object',item) order by rel->>'relname',item->>'name'),'[]'::jsonb) from jsonb_array_elements(src.snapshot_doc->'relations') rel cross join lateral jsonb_array_elements(rel->'constraints') item where (rel->>'relname',item->>'name') in (values ('campaigns','campaigns_publish_state_check'),('creatives','creatives_status_check'),('businesses','businesses_cadastro_estado_check'),('meta_connections','meta_connections_meta_user_id_nao_vazio'),('campaigns','campaigns_ativacao_carimbada_check'),('campaigns','campaigns_ativa_exige_carimbo_check'),('campaigns','campaigns_pausa_carimbada_check'),('campaigns','campaigns_pausada_exige_carimbo_check'))),'indexes',(select coalesce(jsonb_agg(jsonb_build_object('table',rel->>'relname','object',item) order by rel->>'relname',item->>'name'),'[]'::jsonb) from jsonb_array_elements(src.snapshot_doc->'relations') rel cross join lateral jsonb_array_elements(rel->'indexes') item where (rel->>'relname',item->>'name') in (values ('campaigns','campaigns_publishing_idx'),('campaigns','campaigns_publish_key_idx'),('campaigns','campaigns_ativando_idx'),('campaigns','campaigns_esperando_ativacao_idx'),('businesses','businesses_cadastro_estado_idx'),('exclusoes_de_dados','exclusoes_de_dados_meta_user_id_idx'))),'table',(select rel from jsonb_array_elements(src.snapshot_doc->'relations') rel where rel->>'nspname'='public' and rel->>'relname'='exclusoes_de_dados'),'functions',(select coalesce(jsonb_agg(f order by f->>'schema',f->>'name',f->>'identity'),'[]'::jsonb) from jsonb_array_elements(src.snapshot_doc->'functions') f where f->>'name' in ('desautorizar_meta','apagar_dados_da_meta','status_da_exclusao'))) from(select s snapshot_doc) src)) as receipt from(select (select jsonb_build_object(
'relations',(select jsonb_agg(obj order by obj->>'nspname',obj->>'relname') from (select jsonb_build_object('nspname',n.nspname,'relname',c.relname,'relkind',c.relkind,'owner',c.relowner::regrole::text,'rls',c.relrowsecurity,'forced',c.relforcerowsecurity,
'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
