'incoming_fks',(select jsonb_agg(jsonb_build_object('source',k.conrelid::regclass::text,'target',k.confrelid::regclass::text,'name',k.conname,'def',pg_get_constraintdef(k.oid)) order by k.conrelid::regclass::text,k.conname) from pg_constraint k where k.contype='f' and k.confrelid in ('public.meta_connections'::regclass,'public.ad_accounts'::regclass,'public.metrics_daily'::regclass)),
'vault_access',jsonb_build_object('usage',has_schema_privilege('postgres','vault','USAGE'),'select',has_table_privilege('postgres','vault.secrets','SELECT'),'delete',has_table_privilege('postgres','vault.secrets','DELETE'))
)) s) capture;
